-fn measureEncode(init: std.process.Init, input: []const u8, iterations: usize) !Measurement {
+fn measureEncode(init: std.process.Init, input: []const u8, iterations: usize, block_size: u4) !Measurement {
+    var checksum: u64 = 0;
+    const start = std.Io.Clock.awake.now(init.io);
+    for (0..iterations) |_| {
+        const bytes = try encoder.encodeAlloc(init.gpa, input, .{ .block_size_100k = block_size });
