+        std.mem.doNotOptimizeAway(bytes.ptr);
+        init.gpa.free(bytes);
+    }
+    return .{ .ns = @intCast(start.durationTo(std.Io.Clock.awake.now(init.io)).nanoseconds), .checksum = checksum };
+}
